INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c2-e340-73f4-8f57-b19bb153e332', 'ollie', '{"mode":"cond","system":"Resp","name":"Asthma","prompt":"Symptoms and control to ask about","presentation":{"Time course":[{"label":"Night waking","keywords":"night|nocturnal|wak|sleep"}],"Cardiorespiratory":[{"label":"Wheeze","keywords":"wheez"},{"label":"Cough (esp. nocturnal)","keywords":"cough"},{"label":"Chest tightness","keywords":"tight"},{"label":"SOB","keywords":"dysp|sob|breath"}],"Complications":[{"label":"Exacerbations / ED / ICU / intubation","keywords":"exacerb|ed |emergency|icu|intubat|admi|hospital"}],"Impact":[{"label":"Activity limitation","keywords":"activit|exercise|limit"}]},"risks":{"Comorbidities":[{"label":"Rhinitis / eczema (atopy)","keywords":"rhinit|hay fever|eczema|atop|sinus"},{"label":"GORD","keywords":"gord|reflux|heartburn"}],"Triggers":[{"label":"Triggers (allergens, exercise, cold, viral, NSAIDs, smoke)","keywords":"trigger|allerg|pollen|dust|cold air|nsaid|aspirin|pet|smoke"}]},"examination":{"General and vitals":[{"label":"Reduced peak flow / unable to speak full sentences","keywords":"peak flow|pefr|sentences|speak"},{"label":"Silent chest / cyanosis (life-threatening)","keywords":"silent|cyano|spo2|life.?threat"}],"Cardiorespiratory":[{"label":"Tachycardia, pulsus paradoxus","keywords":"tachycard|pulsus|paradox"},{"label":"Prolonged expiratory phase","keywords":"prolong|expir"},{"label":"Tachypnoea / accessory muscle use","keywords":"tachyp|accessory|resp rate"},{"label":"Hyperinflation in chronic disease","keywords":"hyperinfl|barrel"}],"Local and peripheral signs":[{"label":"Atopic features (eczema, nasal polyps, rhinitis)","keywords":"polyp"}]},"investigations":{"Bedside and functional":[{"label":"FeNO raised (eosinophilic airway inflammation)","keywords":"feno|nitric oxide|exhaled"},{"label":"Spirometry: obstructive; bronchodilator reversibility >=12% and 200 mL","keywords":"spirom|fev|reversib|bronchodil|fvc"},{"label":"Peak f