INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-25a8-744f-bfad-3e3e398bea2f', 'ollie', '{"mode":"cond","system":"GI","name":"Colorectal cancer","prompt":"Symptoms to ask about","presentation":{"Systemic":[{"label":"Weight loss / anorexia","keywords":"weight|anorex|appetite"},{"label":"Fatigue / anaemia / SOB","keywords":"fatigue|anaem|tired|sob|breath|dysp"}],"Abdominal and pelvic":[{"label":"Change in bowel habit","keywords":"bowel habit|change|diarr|constip"},{"label":"PR bleeding / mixed blood","keywords":"bleed|blood"},{"label":"Tenesmus / incomplete evacuation","keywords":"tenesm|incomplete"},{"label":"Abdominal pain / mass","keywords":"pain|mass|lump"},{"label":"Obstruction: distension, vomiting, constipation","keywords":"obstruct|distens|vomit|absolute|distend"}],"Complications":[{"label":"Jaundice / RUQ pain (liver mets)","keywords":"jaund|ruq|liver"}]},"risks":{"Comorbidities":[{"label":"IBD history","keywords":"ibd|crohn|colitis"}]},"examination":{"General and vitals":[{"label":"Pallor (anaemia)","keywords":"pallor|pale|anem|anaem"},{"label":"Cachexia / weight loss","keywords":"cachex|wast"}],"Abdomen":[{"label":"Palpable abdominal mass (right iliac fossa / left)","keywords":"palpable|rif|iliac"},{"label":"Abdominal distension / tenderness (obstruction)","keywords":"distend|tender|tinkling|bowel sounds|distens"},{"label":"DRE: palpable rectal mass, blood on glove","keywords":"dre|rectal|glove"}],"Local and peripheral signs":[{"label":"Hernia / stoma / surgical scars","keywords":"hernia|scar"}],"Complications":[{"label":"Hepatomegaly (liver metastases)","keywords":"hepatomeg|mets|metast|craggy"},{"label":"Ascites","keywords":"ascites|shifting|dullness|distens|distend"},{"label":"Virchow''s node (left supraclavicular)","keywords":"virchow|supraclav|node|lymph"}]},"investigations":{"Bloods":[{"label":"CEA: baseline and post-resection surveillance (not diagnostic)","keywords":"cea level|carcinoembryonic|tumour marker|tumor marker"}],"Endoscopy and t