INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-7f80-773c-837c-63dcc78d442c', 'ollie', '{"mode":"cond","system":"Rheum","name":"PMR / GCA","prompt":"Symptoms to ask about","presentation":{"Core symptoms":[{"label":"Shoulder / hip girdle pain and stiffness","keywords":"shoulder|hip|girdle|stiff"},{"label":"Jaw claudication","keywords":"jaw|chew"}],"Systemic":[{"label":"Fever / weight loss / fatigue","keywords":"fever|weight|fatigue"}],"Cardiorespiratory":[{"label":"Arm claudication","keywords":"arm"}],"Neurological":[{"label":"New headache","keywords":"headache"}],"Musculoskeletal and skin":[{"label":"Morning stiffness","keywords":"morning"},{"label":"Difficulty rising / combing hair","keywords":"rising|chair|comb|arms up"},{"label":"Scalp tenderness","keywords":"scalp|comb"}],"Special senses":[{"label":"Visual loss / diplopia / amaurosis","keywords":"vision|visual|diplop|amauros|blind"}]},"risks":[],"examination":{"General and vitals":[{"label":"Low-grade fever, weight loss","keywords":"temp|fever"}],"Cardiorespiratory":[{"label":"Absent / asymmetric upper limb pulses and BP, bruits (large-vessel GCA)","keywords":"asymmetr|bruit|subclavian|large.?vessel|bp"}],"Neurological":[{"label":"Visual acuity, fields, relative afferent pupillary defect","keywords":"acuity|field|rapd|pupil|afferent|fundos"},{"label":"Pale swollen optic disc (ischaemic optic neuropathy)","keywords":"optic|disc|pale|swollen|papill"}],"Musculoskeletal and skin":[{"label":"Proximal muscle tenderness / stiffness (shoulders, hips)","keywords":"proximal|muscle"},{"label":"Normal power but pain-limited movement","keywords":"power|normal|pain|limited"},{"label":"Reduced active shoulder range of motion","keywords":"range|motion|active|abduct"}],"Local and peripheral signs":[{"label":"Carpal tunnel / peripheral synovitis (distal)","keywords":"carpal|synovit|distal|wrist"},{"label":"Tender, thickened, non-pulsatile temporal arteries","keywords":"artery|arteries|thicken|beaded"},{"label":"Scalp tenderness (pain on hair brushing)","keywords":"brush"}]},"investigations":{"Bloods":[{"label":"ESR / CRP markedly raised (ESR often >50); anaemia, thrombocytosis, raised ALP","keywords":"esr|crp|inflammatory marker|c-reactive|thrombocytosis|raised alp|anaemia"},{"label":"CK normal, RF / anti-CCP negative (exclude myositis / RA mimics)","keywords":"ck|creatine kinase|myositis|rf|ccp|rheumatoid"}],"Imaging":[{"label":"Temporal artery ultrasound: halo sign, non-compressible artery","keywords":"temporal artery ultra|halo|duplex|doppler|ultrasound"},{"label":"PET-CT / CT or MR angiography: large-vessel GCA (aortitis, subclavian / axillary stenosis)","keywords":"pet|angiograph|large vessel imag|aortitis|ct angio|mra"}],"Endoscopy and tissue":[{"label":"Temporal artery biopsy (ideally within 1-2 weeks of steroids): giant cells, granulomatous inflammation, skip lesions","keywords":"biopsy|giant cell|granulomat|skip lesion"}],"Screening and monitoring":[{"label":"Steroid monitoring: HbA1c / BSL, lipids, DEXA bone density","keywords":"dexa|dxa|bone density|hba1c|baseline glucose"}]},"medications":{"Acute and first line":[{"label":"PMR: prednisolone ~15 mg with slow taper","keywords":"15 mg|15mg|prednis|steroid|taper"},{"label":"GCA: high-dose prednisolone 40-60 mg (IV methylpred if visual loss)","keywords":"40|60 mg|high-dose|high dose|methylpred|ivmp|pulse"}],"Escalation and disease-modifying":[{"label":"Tocilizumab (GCA, steroid-sparing)","keywords":"tocilizumab|actemra|il-6|il6|steroid-sparing|steroid sparing"},{"label":"Methotrexate (steroid-sparing)","keywords":"methotrexate|mtx"}],"Prevention and monitoring":[{"label":"Bone protection ± PPI","keywords":"bone protect|bisphosph|alendron|calcium|vitamin d|ppi|~prazole"}]},"deleted":false}');
INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-8368-77b0-95ba-3c7bfd802795', 'ollie', '{"mode":"cond","system":"Neuro","name":"Parkinson''s disease","prompt":"Motor, non-motor and treatment symptoms","presentation":{"Prodromal":[{"label":"Loss of smell","keywords":"smell|anosm"},{"label":"Acting out dreams (RBD)","keywords":"dream|rbd|rem|sleep behav"},{"label":"Sleep / daytime sleepiness","keywords":"sleep|insomn|drows"},{"label":"Constipation","keywords":"constip"}],"Neurological":[{"label":"Depression / anxiety / apathy","keywords":"depress|anxi|apath|mood"},{"label":"Cognition / memory","keywords":"memory|cognit|demen"},{"label":"Hallucinations","keywords":"hallucin|psychos|seeing things"},{"label":"Tremor (rest, side of onset)","keywords":"tremor|shak"},{"label":"Slowness / bradykinesia","keywords":"slow|bradykin|akines"},{"label":"Stiffness","keywords":"stiff|rigid"},{"label":"Shuffling / freezing / turning","keywords":"shuffl|freez|gait|turn"},{"label":"Falls","keywords":"fall"},{"label":"Small handwriting","keywords":"handwrit|microgr|writing"},{"label":"Fine motor: buttons, turning in bed","keywords":"button|bed|dress|fine motor"},{"label":"Pain","keywords":"pain"},{"label":"Urinary symptoms","keywords":"urin|bladder|nocturia"},{"label":"Postural dizziness","keywords":"postural|dizz|lighthead|orthostat"},{"label":"Sexual dysfunction","keywords":"sexual|erect"},{"label":"Soft voice","keywords":"voice|speech|hypophon"},{"label":"Reduced facial expression","keywords":"facial|expression|mask"},{"label":"Swallowing / drooling","keywords":"swallow|dysphag|drool|saliva"}]},"risks":[],"examination":{"Cardiorespiratory":[{"label":"Postural hypotension (autonomic)","keywords":"hypotens|autonomic"}],"Neurological":[{"label":"Resting pill-rolling tremor (asymmetric)","keywords":"pill|rolling|rest"},{"label":"Cogwheel rigidity / lead-pipe","keywords":"cogwheel|lead.?pipe|tone"},{"label":"Dyskinesias (levodopa-induced)","keywords":"chorea"},{"label":"Bradykinesia: slow finger tapping, reduced amplitude","keywords":"finger tap|amplitude|sequence|bradykinesia"},{"label":"Hypomimia (mask-like face), reduced blink","keywords":"hypomimia|face|blink"},{"label":"Hypophonia / monotonous speech","keywords":"monoton|soft|hypophonia"},{"label":"Shuffling gait, reduced arm swing, festination, freezing, difficulty turning","keywords":"arm swing|festinat"}],"Special tests":[{"label":"Postural instability (pull test)","keywords":"pull test|instab|balance"},{"label":"Glabellar tap; impaired upgaze (PSP) / cerebellar signs (MSA)","keywords":"glabella|upgaze|psp|msa|cerebell|vertical gaze"}]},"investigations":{"Bedside and functional":[{"label":"Acute levodopa challenge: >30% motor improvement supports PD","keywords":"challenge|levodopa response|response to levodopa|apomorphine challenge"},{"label":"Lying / standing BP: orthostatic drop (autonomic failure suggests MSA / Lewy body)","keywords":"lying and standing|lying.standing|standing bp|orthostatic bp|tilt table"}],"Bloods":[{"label":"Caeruloplasmin / copper (Wilson''s) if onset <40 years","keywords":"caeruloplasmin|ceruloplasmin|wilson|copper"}],"Imaging":[{"label":"Clinical diagnosis; MRI brain to exclude mimics (vascular parkinsonism, NPH); hummingbird (PSP) / hot cross bun (MSA)","keywords":"mri|ct brain|hummingbird|hot cross|neuroimag|imaging"},{"label":"DaTscan (FP-CIT SPECT): reduced striatal uptake if diagnosis uncertain (vs essential tremor, drug-induced)","keywords":"datscan|dat scan|spect|fp.cit|dopamine transporter"}]},"medications":{"Acute and first line":[{"label":"Levodopa (Sinemet, Madopar)","keywords":"levodopa|l-dopa|ldopa|sinemet|madopar|carbidopa|benserazide|stalevo"},{"label":"Dopamine agonists (pramipexole, ropinirole, rotigotine)","keywords":"dopamine agonist|agonist|pramipexole|sifrol|ropinirole|rotigotine|neupro|apomorphine"}],"Escalation and disease-modifying":[{"label":"MAO-B / COMT inhibitors","keywords":"mao|rasagiline|azilect|safinamide|selegiline|entacapone|comtan|opicapone|comt"},{"label":"Amantadine (dyskinesia)","keywords":"amantadine"}],"Procedural":[{"label":"Device therapies (DBS, levodopa infusion)","keywords":"dbs|deep brain|duodopa|infusion|pump|foslevodopa"}],"Non-drug":[{"label":"Allied health (physio, speech, OT)","keywords":"physio|speech|ot|occupational|allied|multidisciplin"}],"Prevention and monitoring":[{"label":"Avoid dopamine antagonists (metoclopramide, haloperidol)","keywords":"metoclopramide|maxolon|haloperidol|antipsychotic|dopamine antag"}]},"deleted":false}');
INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-8750-7508-8c61-54a841c43ad0', 'ollie', '{"mode":"cond","system":"Neuro","name":"Multiple sclerosis","prompt":"Symptoms to ask about","presentation":{"Time course":[{"label":"Heat sensitivity (Uhthoff)","keywords":"heat|uhthoff|hot shower"},{"label":"Relapses (number, recovery)","keywords":"relapse|attack|flare"}],"Systemic":[{"label":"Fatigue","keywords":"fatigue|tired"}],"Neurological":[{"label":"Balance / ataxia / vertigo","keywords":"balance|ataxi|vertig|clums|coordinat"},{"label":"Cognition / mood","keywords":"cognit|memory|mood|depress"},{"label":"Weakness","keywords":"weak"},{"label":"Walking distance / aids","keywords":"walk|aid|stick|mobility"},{"label":"Spasticity / spasms","keywords":"spastic|spasm|stiff"},{"label":"Numbness / tingling","keywords":"numb|tingl|sensory|pins"},{"label":"Lhermitte''s (electric shock on neck flexion)","keywords":"lhermitte|electric|shock"},{"label":"Pain","keywords":"pain"},{"label":"Bladder (urgency, retention)","keywords":"bladder|urin|urgen|retention"},{"label":"Bowel","keywords":"bowel|constip|incontin"},{"label":"Sexual dysfunction","keywords":"sexual|erect"}],"Special senses":[{"label":"Visual loss / painful eye movements (optic neuritis)","keywords":"vision|visual|optic|eye pain|blur"},{"label":"Double vision","keywords":"diplop|double"}]},"risks":[],"examination":{"Abdomen":[{"label":"Bladder: palpable bladder / retention","keywords":"palpable|bladder"}],"Neurological":[{"label":"Internuclear ophthalmoplegia (slowed adduction, nystagmus in abducting eye)","keywords":"internuclear|ino|ophthalmoplegia|adduction|nystagmus"},{"label":"Spastic paraparesis: increased tone, brisk reflexes, upgoing plantars","keywords":"tone|reflex|plantar|babinski|upgoing|clonus"},{"label":"Weakness (pyramidal pattern)","keywords":"power|pyramidal|paresis|weak"},{"label":"Gait abnormality","keywords":"gait"},{"label":"Cerebellar signs: intention tremor, dysdiadochokinesia, ataxia","keywords":"cerebell|intention|dysdiadochokin|dysmetria"},{"label":"Scanning speech","keywords":"scanning|speech|dysarthria"},{"label":"Sensory loss (sensory level, vibration/proprioception loss)","keywords":"sensation|vibration|proprioception|level"},{"label":"Optic neuritis / RAPD, pale optic disc","keywords":"rapd|pupil|disc|pale|acuity|colour"}]},"investigations":{"Bedside and functional":[{"label":"Visual evoked potentials: delayed P100 latency","keywords":"vep|visual evoked|evoked potential|p100"}],"Bloods":[{"label":"Exclude mimics: aquaporin-4 (NMOSD) and MOG antibodies, B12, TFT, ANA, HIV / syphilis","keywords":"aqp4|aquaporin|nmo|mog|mimic|autoantibod"}],"Imaging":[{"label":"MRI brain + spine with gadolinium: periventricular, juxtacortical, infratentorial, spinal lesions (Dawson''s fingers); enhancing = active","keywords":"mri|gadolinium|periventric|dawson|t2 lesion|enhanc|dissemination"},{"label":"OCT: retinal nerve fibre layer thinning after optic neuritis","keywords":"oct|optical coherence|rnfl|nerve fibre layer"}],"Endoscopy and tissue":[{"label":"LP / CSF: oligoclonal bands (unmatched in serum), raised IgG index","keywords":"lp|lumbar puncture|csf|oligoclonal|igg index"}],"Screening and monitoring":[{"label":"Pre-DMT / monitoring: JC virus serology (natalizumab PML risk), hepatitis B / VZV serology, lymphocyte count, LFTs, annual MRI","keywords":"jc|jcv|john cunningham|pml|lymphocyte count|annual mri|surveillance mri|baseline serology"}]},"medications":{"Acute and first line":[{"label":"Relapse: IV methylprednisolone","keywords":"methylpred|steroid|ivmp|pulse"}],"Escalation and disease-modifying":[{"label":"High-efficacy DMTs (ocrelizumab, natalizumab, ofatumumab)","keywords":"ocrelizumab|ocrevus|natalizumab|tysabri|ofatumumab|kesimpta|alemtuzumab|cladribine|mavenclad|~mab|dmt|disease modifying"},{"label":"Oral DMTs (fingolimod, dimethyl fumarate, teriflunomide)","keywords":"fingolimod|gilenya|siponimod|ozanimod|dimethyl fumarate|tecfidera|teriflunomide|aubagio|oral dmt"}],"Symptomatic and palliative":[{"label":"Symptomatic: baclofen, bladder meds, fampridine","keywords":"baclofen|spastic|oxybutynin|bladder|fampridine|gabapentin|symptomatic"}],"Prevention and monitoring":[{"label":"Vitamin D","keywords":"vitamin d"}]},"deleted":false}');
INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-8b38-741f-be08-5868f3191799', 'ollie', '{"mode":"cond","system":"Neuro","name":"Stroke","prompt":"Symptoms, deficits and risk to ask about","presentation":{"Time course":[{"label":"Headache / onset timing","keywords":"headache|onset|sudden|time"}],"Systemic":[{"label":"Fatigue","keywords":"fatigue"}],"Neurological":[{"label":"Neglect / attention","keywords":"neglect|ignor"},{"label":"Cognition / memory","keywords":"cognit|memory|confus"},{"label":"Balance / coordination","keywords":"balance|ataxi|coordinat|vertig|dizz"},{"label":"Weakness (side, limbs)","keywords":"weak|hemipar"},{"label":"Numbness / sensory","keywords":"numb|sensory|tingl"},{"label":"Speech / language difficulty","keywords":"speech|aphas|word|language|dysarth|slur"},{"label":"Facial droop","keywords":"face|facial|droop"},{"label":"Swallow problems","keywords":"swallow|dysphag|choke|cough when"}],"Special senses":[{"label":"Vision loss / field cut","keywords":"vision|visual|field|hemianop"}],"Complications":[{"label":"Mood / emotionalism","keywords":"mood|depress|emotion|cry"},{"label":"Continence","keywords":"contin|bladder|bowel|urin"},{"label":"Pain / shoulder pain / spasticity","keywords":"pain|shoulder|spastic|stiff"}]},"risks":{"Comorbidities":[{"label":"Palpitations (AF)","keywords":"palpit|af|irregular"},{"label":"Previous TIAs","keywords":"tia|previous"},{"label":"Vascular RFs: HTN, DM, lipids, smoking, AF","keywords":"hypertens|bp|diabet|cholest|lipid|smok|af"}]},"examination":{"Cardiorespiratory":[{"label":"Carotid bruit","keywords":"bruit|carotid"},{"label":"Irregular pulse (AF)","keywords":"fibrillation|pulse"}],"Neurological":[{"label":"Facial droop (UMN pattern, forehead sparing)","keywords":"umn|forehead"},{"label":"Arm / leg weakness (hemiparesis), pronator drift","keywords":"drift|power|pronator"},{"label":"Hemisensory loss","keywords":"sensation|hemisens"},{"label":"Speech: dysarthria / expressive or receptive dysphasia","keywords":"dysphasia|speech"},{"label":"Visual field defect (homonymous hemianopia)","keywords":"homonymous"},{"label":"Neglect / inattention","keywords":"inattention|neglect"},{"label":"Cerebellar signs / gait ataxia (posterior circulation)","keywords":"cerebell|gait|nystagmus|dysmetria"}],"Special tests":[{"label":"Swallow screen / aspiration","keywords":"aspirat"},{"label":"NIHSS / GCS assessment","keywords":"nihss|gcs|glasgow|score"}]},"investigations":{"Bedside and functional":[{"label":"ECG + prolonged rhythm monitoring (Holter / implantable loop recorder): paroxysmal AF","keywords":"ecg|holter|loop recorder|telemetry|rhythm monitor|event monitor"}],"Imaging":[{"label":"Urgent non-contrast CT brain: excludes haemorrhage; early ischaemic change, hyperdense MCA sign","keywords":"ct brain|ct head|non-contrast|non contrast|hyperdense|exclude haemorrhage"},{"label":"CT angiogram + perfusion (CTA / CTP): large vessel occlusion, penumbra for thrombectomy","keywords":"cta|ctp|angiogram|perfusion|large vessel|lvo|penumbra"},{"label":"MRI brain with DWI: restricted diffusion (best for small / posterior circulation infarcts)","keywords":"mri|dwi|diffusion"},{"label":"Carotid imaging (duplex US / CTA neck): symptomatic stenosis >50-70%","keywords":"carotid duplex|carotid imaging|duplex|doppler|stenosis|cta neck"},{"label":"Echo (TTE / TOE): LV thrombus, vegetations, PFO / bubble study, low EF","keywords":"echo|toe|pfo|bubble"}]},"medications":{"Acute and first line":[{"label":"Acute: thrombolysis / thrombectomy","keywords":"thromboly|tpa|alteplase|tenecteplase|lysis|thrombectomy|ecr|clot retrieval"}],"Procedural":[{"label":"Carotid endarterectomy / stenting","keywords":"endarterect|carotid stent"}],"Non-drug":[{"label":"Rehab (physio, OT, speech)","keywords":"rehab|physio|speech|ot|occupational|allied"}],"Prevention and monitoring":[{"label":"Antiplatelet (aspirin, clopidogrel; short-term DAPT)","keywords":"aspirin|antiplatelet|clopidogrel|plavix|dapt|ticagrelor"},{"label":"Anticoagulation if AF","keywords":"doac|noac|apixaban|rivaroxaban|dabigatran|warfarin|anticoag"},{"label":"Statin","keywords":"statin|~statin"},{"label":"BP lowering (ACEi ± thiazide-like)","keywords":"antihypert|blood pressure|acei|~pril|~sartan|indapamide"}]},"deleted":false}');
INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-8f20-75c1-87f1-68df0c6fbfa1', 'ollie', '{"mode":"cond","system":"Neuro","name":"Epilepsy / seizure","prompt":"History to ask about","presentation":{"Core symptoms":[{"label":"During: witness account","keywords":"witness|collateral|describe|during"},{"label":"Stiffening / jerking","keywords":"jerk|stiff|tonic|clonic|shak"},{"label":"Tongue biting (lateral)","keywords":"tongue"},{"label":"Incontinence","keywords":"incontin|wet|urin"},{"label":"Eyes open / colour change","keywords":"eyes|colour|color|cyan|blue"},{"label":"Absences / myoclonic jerks","keywords":"absence|stare|myoclon|blank"}],"Time course":[{"label":"Duration","keywords":"duration|how long|minute"},{"label":"Frequency / last seizure","keywords":"frequen|last seizure|how often|seizure free"}],"Prodromal":[{"label":"Before: aura, warning, trigger","keywords":"aura|warning|before|trigger|deja"}],"Postdromal":[{"label":"After: confusion, drowsiness, Todd''s","keywords":"confus|drows|post.?ictal|todd|after|tired"}],"Complications":[{"label":"Injuries","keywords":"injur"}]},"risks":{"Triggers":[{"label":"Triggers: sleep deprivation, alcohol, missed meds, flashing lights","keywords":"sleep|alcohol|missed|flash|light|stress"}]},"examination":{"General and vitals":[{"label":"Signs of alcohol / drug withdrawal, intoxication","keywords":"withdraw|drug|intoxic|substance"}],"Cardiorespiratory":[{"label":"Cardiovascular exam: pulse, BP, murmur (exclude syncope)","keywords":"pulse|bp|blood pressure|murmur|syncope|cardio|postural"}],"Neurological":[{"label":"Often normal examination interictally","keywords":"normal|interictal|unremarkable"},{"label":"Focal neurological deficit (structural lesion)","keywords":"focal|deficit|weak|hemipar|neuro"},{"label":"Cognitive / mood screen","keywords":"cognit|memory|depress"},{"label":"Postictal state: drowsiness, confusion, Todd''s paresis","keywords":"post.?ictal"}],"Local and peripheral signs":[{"label":"Neurocutaneous stigmata (café-au-lait, ash-leaf, adenoma sebaceum)","keywords":"cafe|café|ash.?leaf|adenoma|sebaceum|port.?wine"},{"label":"Gingival hypertrophy / hirsutism (phenytoin)","keywords":"gingival|hirsut|gum"}],"Complications":[{"label":"Tongue bite (lateral), incontinence","keywords":"bite"},{"label":"Injuries (head, shoulder dislocation)","keywords":"dislocat|bruis|head|trauma|injur"}]},"investigations":{"Bedside and functional":[{"label":"ECG: long QT / arrhythmia to exclude convulsive syncope","keywords":"ecg|long qt|qtc|holter"},{"label":"EEG (routine / sleep-deprived / ambulatory): interictal epileptiform discharges; 3 Hz spike-wave in absence","keywords":"eeg|electroenceph|spike|3 hz|epileptiform"},{"label":"Video-EEG telemetry: differentiates epileptic from functional (non-epileptic) events; localises focus","keywords":"video|telemetry|pnes|non-epileptic|functional seizure"}],"Bloods":[{"label":"Bloods at first seizure: glucose, Na, Ca, Mg, renal function, LFTs (provoked / metabolic cause)","keywords":"glucose|bsl|bgl|sodium|electrolyte|metabolic|calcium|magnesium|first seizure bloods"},{"label":"Drug levels (phenytoin, valproate, carbamazepine) if toxicity or breakthrough seizures","keywords":"drug level|therapeutic drug|tdm|serum level|phenytoin level|asm level"}],"Imaging":[{"label":"MRI brain (epilepsy protocol): hippocampal sclerosis, cortical dysplasia, tumour, cavernoma, gliosis","keywords":"mri|hippocamp|dysplasia|mesial|cavernoma|neuroimag"}]},"medications":{"Acute and first line":[{"label":"Rescue: buccal / intranasal midazolam","keywords":"midazolam|rescue|buccal|intranasal|benzo|diazepam|seizure plan"},{"label":"Levetiracetam","keywords":"levetiracetam|keppra|brivaracetam"},{"label":"Sodium valproate (avoid in people who could become pregnant)","keywords":"valproate|epilim|valpro"},{"label":"Lamotrigine","keywords":"lamotrigine|lamictal"}],"Escalation and disease-modifying":[{"label":"Other ASMs (carbamazepine, lacosamide, topiramate)","keywords":"carbamazepine|tegretol|lacosamide|vimpat|oxcarbazepine|phenytoin|topiramate|clobazam|zonisamide|perampanel"}],"Prevention and monitoring":[{"label":"Folic acid if planning pregnancy","keywords":"folic|folate"}]},"deleted":false}');
INSERT INTO quizzes (id, owner_id, data) VALUES ('01a0f4c3-9308-7270-a9f2-ec33b3dd2c8b', 'ollie', '{"mode":"cond","system":"Neuro","name":"Dementia","prompt":"History to ask about (incl. collateral)","presentation":{"Core symptoms":[{"label":"Memory: recent vs remote, repetitive questioning","keywords":"memory|forget|repeat"},{"label":"Getting lost / disorientation","keywords":"lost|disorient|orient"},{"label":"Word-finding / language","keywords":"word|language|speech"},{"label":"Executive: finances, bills, planning","keywords":"financ|bill|money|plan|manage"},{"label":"Fluctuations (DLB)","keywords":"fluctuat"}],"Time course":[{"label":"Timeline: gradual vs stepwise","keywords":"gradual|stepwise|onset|timeline|progress"}],"Neurological":[{"label":"Personality / behaviour change","keywords":"personal|behavio|disinhib|aggress|agitat"},{"label":"Mood / apathy","keywords":"mood|depress|apath"},{"label":"Hallucinations / delusions / paranoia","keywords":"hallucin|delusion|paranoi|psychos"},{"label":"Sleep / acting out dreams","keywords":"sleep|dream"},{"label":"Parkinsonism / falls","keywords":"parkins|tremor|fall|gait"},{"label":"Continence","keywords":"contin|urin|bladder"}],"Impact":[{"label":"ADLs / IADLs","keywords":"adl|iadl|shopping|cooking|dress|wash"}]},"risks":{"Drugs and procedures":[{"label":"Alcohol / meds (anticholinergics, benzos)","keywords":"alcohol|medic|anticholin|benzo|sedat"}],"Comorbidities":[{"label":"Vascular RFs / strokes","keywords":"stroke|vascular|hypertens|diabet"}]},"examination":{"General and vitals":[{"label":"Weight loss / nutrition / self-neglect","keywords":"weight|neglect|hygiene"}],"Neurological":[{"label":"Cognitive screen: MMSE / MoCA / ACE-III, clock drawing","keywords":"mmse|moca|ace|clock|cognit|screen|score"},{"label":"Orientation, attention, recall","keywords":"attention|recall"},{"label":"Frontal release signs (grasp, palmomental, glabellar)","keywords":"frontal|release|grasp|palmomental|glabell|primitive"},{"label":"Gait: ma